import { unstable_cache } from 'next/server'
import { getAllProducts } from './db.js'

// Catalog reads are read-heavy, so serve them from the Data Cache keyed by the
// "products" tag. Any catalog view that depends on this data should call this
// accessor instead of the raw database function so browsing stays fast and
// invalidation is consistent across views.
export const getCachedProducts = unstable_cache(
  async () => {
    return getAllProducts()
  },
  ['products'],
  {
    tags: ['products'],
  }
)

