import { getCachedProducts } from '@/lib/products'

// Sync is a potentially long-running ERP/PIM refresh that can touch thousands
// of SKUs. Admins should not have to wait for it to finish before they can keep
// working, so the Server Action only kicks off the cache invalidation and
// returns immediately. The catalog stays briefly stale and becomes up to date
// in the background as the tagged cache entries are regenerated.
async function syncCatalog() {
  'use server'

  // Revalidate every cache entry tagged "products" across all views that
  // depend on the catalog. The next read for each view will recompute fresh
  // data on demand; we do not block here while that happens.
  revalidateTag('products')
}

export const dynamic = 'force-dynamic'

export default async function CatalogPage() {
  const products = await getCachedProducts()

  return (
    <main style={{ fontFamily: 'system-ui, sans-serif', maxWidth: 900, margin: '0 auto', padding: 24 }}>
      <header style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 24 }}>
        <div>
          <h1 style={{ margin: 0 }}>Product Catalog</h1>
          <p style={{ margin: '4px 0 0', color: '#666' }}>
            Cached for fast browsing. Sync pulls the latest ERP/PIM data.
          </p>
        </div>
        <form action={syncCatalog}>
          <button
            type="submit"
            style={{
              padding: '10px 16px',
              fontSize: 14,
              fontWeight: 600,
              background: '#111',
              color: '#fff',
              border: 'none',
              borderRadius: 6,
              cursor: 'pointer',
